"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import { EditModal } from "@/components/ui/edit-modal"

interface Campaign {
  id: number
  subject: string
  html: string
  created_by: number
  created_at: string
  status: string
}

interface List {
  id: number
  name: string
  slug: string
  contact_count: number
}

export default function Campaigns() {
  const [campaigns, setCampaigns] = useState<Campaign[]>([])
  const [lists, setLists] = useState<List[]>([])
  const [loading, setLoading] = useState(true)
  const [showCreateForm, setShowCreateForm] = useState(true)
  const [previewCampaign, setPreviewCampaign] = useState<Campaign | null>(null)
  const [editingCampaign, setEditingCampaign] = useState<Campaign | null>(null)
  const [editModalOpen, setEditModalOpen] = useState(false)
  const [newCampaign, setNewCampaign] = useState({
    subject: "",
    html: "",
    list_id: 0
  })
  const router = useRouter()

  useEffect(() => {
    loadCampaigns()
    loadLists()
  }, [])

  const loadCampaigns = async () => {
    try {
      const token = localStorage.getItem("auth_token")
      
      if (!token) {
        router.push("/")
        return
      }

      const response = await fetch("/api/campaigns", {
        headers: { "Authorization": `Bearer ${token}` }
      })
      
      if (response.ok) {
        const data = await response.json()
        setCampaigns(data.campaigns || [])
      }
    } catch (error) {
      console.error("Error loading campaigns:", error)
    } finally {
      setLoading(false)
    }
  }

  const loadLists = async () => {
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch("/api/lists/", {
        headers: { "Authorization": `Bearer ${token}` }
      })
      
      if (response.ok) {
        const data = await response.json()
        setLists(data.lists || [])
      }
    } catch (error) {
      console.error("Error loading lists:", error)
    }
  }

  const handleCreateCampaign = async (e: React.FormEvent) => {
    e.preventDefault()
    
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch("/api/campaigns", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify(newCampaign)
      })

      if (response.ok) {
        setNewCampaign({ subject: "", html: "", list_id: 0 })
        setShowCreateForm(false)
        loadCampaigns()
      }
    } catch (error) {
      console.error("Error creating campaign:", error)
    }
  }

  const openEditModal = (campaign: Campaign) => {
    setEditingCampaign(campaign)
    setEditModalOpen(true)
  }

  const handleEditCampaign = async (updatedData: { subject: string; html: string }) => {
    if (!editingCampaign) return
    
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch(`/api/campaigns/${editingCampaign.id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify(updatedData)
      })

      if (response.ok) {
        loadCampaigns()
        setEditModalOpen(false)
        setEditingCampaign(null)
      }
    } catch (error) {
      console.error("Error updating campaign:", error)
    }
  }

  const handleSendCampaign = async (campaignId: number) => {
    try {
      const token = localStorage.getItem("auth_token")
      const response = await fetch(`/api/campaigns/${campaignId}/send`, {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${token}`
        }
      })

      if (response.ok) {
        loadCampaigns()
      }
    } catch (error) {
      console.error("Error sending campaign:", error)
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'sent': return 'bg-green-100 text-green-800'
      case 'draft': return 'bg-yellow-100 text-yellow-800'
      case 'sending': return 'bg-blue-100 text-blue-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Cargando campañas...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center space-x-4">
              <Button variant="ghost" onClick={() => router.push("/dashboard")}>
                ← Dashboard
              </Button>
              <h1 className="text-2xl font-bold text-gray-900">Campañas</h1>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Create Campaign Form */}
          {showCreateForm && (
            <Card>
              <CardHeader>
                <CardTitle>Crear Nueva Campaña</CardTitle>
                <CardDescription>
                  Diseña tu campaña de email
                </CardDescription>
              </CardHeader>
              <CardContent>
                <form onSubmit={handleCreateCampaign} className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="subject">Asunto *</Label>
                    <Input
                      id="subject"
                      type="text"
                      placeholder="Ej: Nueva clase de Pole Sport"
                      value={newCampaign.subject}
                      onChange={(e) => setNewCampaign({ ...newCampaign, subject: e.target.value })}
                      required
                    />
                  </div>
                  
                  <div className="space-y-2">
                    <Label htmlFor="list">Lista de Destino *</Label>
                    <select
                      id="list"
                      className="w-full p-2 border border-gray-300 rounded-md"
                      value={newCampaign.list_id}
                      onChange={(e) => setNewCampaign({ ...newCampaign, list_id: parseInt(e.target.value) })}
                      required
                    >
                      <option value={0}>Selecciona una lista</option>
                      {lists.map((list) => (
                        <option key={list.id} value={list.id}>
                          {list.name} ({list.contact_count} contactos)
                        </option>
                      ))}
                    </select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="html">Contenido HTML *</Label>
                    <textarea
                      id="html"
                      className="w-full h-40 p-3 border border-gray-300 rounded-md resize-none"
                      placeholder="<h1>¡Hola {{nombre}}!</h1>&#10;<p>Te invitamos a nuestra nueva clase de {{tema}}...</p>&#10;<p>Variables disponibles: {{nombre}}, {{tema}}</p>"
                      value={newCampaign.html}
                      onChange={(e) => setNewCampaign({ ...newCampaign, html: e.target.value })}
                      required
                    />
                    <p className="text-xs text-gray-500">
                      Variables disponibles: {`{{nombre}}, {{tema}}, {{email}}`}
                    </p>
                  </div>

                  <div className="flex space-x-2">
                    <Button type="submit" className="flex-1">
                      Crear Campaña
                    </Button>
                    <Button 
                      type="button" 
                      variant="outline" 
                      onClick={() => setNewCampaign({ subject: "", html: "", list_id: 0 })}
                    >
                      Limpiar
                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          )}

          {/* Campaigns List */}
          <div className="lg:col-span-2">
            <Card>
              <CardHeader>
                <CardTitle>Campañas ({campaigns.length})</CardTitle>
                <CardDescription>
                  Gestiona tus campañas de email
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {campaigns.length === 0 ? (
                    <p className="text-gray-500 text-center py-8">
                      No hay campañas creadas
                    </p>
                  ) : (
                    campaigns.map((campaign) => (
                      <div key={campaign.id} className="flex items-center justify-between p-4 border rounded-lg">
                        <div className="flex-1">
                          <div className="flex items-center space-x-3">
                            <h3 className="font-medium">{campaign.subject}</h3>
                            <Badge className={getStatusColor(campaign.status)}>
                              {campaign.status}
                            </Badge>
                          </div>
                          <p className="text-sm text-gray-600 mt-1">
                            {campaign.html.substring(0, 100)}...
                          </p>
                          <p className="text-xs text-gray-400">
                            Creada: {new Date(campaign.created_at).toLocaleDateString()}
                          </p>
                        </div>
                        <div className="flex space-x-2">
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => setPreviewCampaign(campaign)}
                          >
                            Previsualizar
                          </Button>
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => handleSendCampaign(campaign.id)}
                          >
                            Enviar
                          </Button>
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => openEditModal(campaign)}
                          >
                            Editar
                          </Button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </CardContent>
            </Card>
          </div>
        </div>

        {/* Preview Modal */}
        {previewCampaign && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <Card className="w-full max-w-4xl max-h-[80vh] overflow-y-auto">
              <CardHeader>
                <div className="flex justify-between items-center">
                  <div>
                    <CardTitle>Previsualización: {previewCampaign.subject}</CardTitle>
                    <CardDescription>
                      Vista previa del email
                    </CardDescription>
                  </div>
                  <Button 
                    variant="ghost" 
                    onClick={() => setPreviewCampaign(null)}
                  >
                    ✕
                  </Button>
                </div>
              </CardHeader>
              <CardContent>
                <div className="border rounded-lg p-4 bg-white">
                  <div 
                    className="prose max-w-none"
                    dangerouslySetInnerHTML={{ __html: previewCampaign.html }}
                  />
                </div>
              </CardContent>
            </Card>
          </div>
        )}
      </main>
    </div>
  )
}
